mapper.select:
/* selectBatchConfig */ SELECT bat_id, bat_nm, job_class, job_class as bat_cls_nm, use_yn, use_yn as usg_yn, cron_expr, sort_sn, desc_txt FROM sys_batch_config WHERE 1=1
AND bat_id = #{bat_id}
ORDER BY CAST(bat_id AS BIGINT) ASC

mapper.update:
/* updateBatch */
UPDATE sys_batch_config
SET bat_nm = #{bat_nm}
   ,job_class = #{bat_cls_nm}
   ,cron_expr = COALESCE(#{cron_expr}, cron_expr)
   ,use_yn = #{use_yn}
   ,sort_sn = COALESCE(#{sort_sn}, sort_sn)
   ,desc_txt = #{desc_txt}
   ,upt_user_id = #{sess_user_id}
   ,upt_date = CURRENT_TIMESTAMP
WHERE bat_id = #{bat_id}

mapper.select:
/* getClassName */
SELECT job_class
FROM sys_batch_config
WHERE bat_id = #{param}

mapper.update:
/* updateBatchRunHis */
UPDATE sys_batch_run_his
SET end_dtm = CURRENT_TIMESTAMP
   ,rslt_cd = #{rslt_cd}
   ,rslt_txt = #{rslt_txt}
WHERE run_sn = #{run_sn}

mapper.select:
/* selectBatchRunHisList */ SELECT run_sn AS bat_exe_log_sn, bat_id, start_dtm AS exe_dtm, end_dtm, rslt_cd, CASE WHEN rslt_txt IS NULL OR rslt_txt = '' THEN NULL WHEN char_length(rslt_txt) <= 400 THEN rslt_txt ELSE CASE WHEN regexp_replace(substring(rslt_txt FROM 1 FOR 450), E'\\n[^\\n]*$', '') = '' THEN substring(rslt_txt FROM 1 FOR 400) ELSE regexp_replace(substring(rslt_txt FROM 1 FOR 450), E'\\n[^\\n]*$', '') || E'\\n…(전문은 결과보기·/batch/run-his/detail)' END END AS rslt_txt, (char_length(rslt_txt) > 400) AS rslt_txt_truncated, (rslt_txt IS NOT NULL AND rslt_txt <> '') AS has_rslt_txt, crt_user_id, crt_date FROM sys_batch_run_his
AND bat_id = #{bat_id}
ORDER BY run_sn DESC
LIMIT #{limit}
LIMIT 200

/* batch.selectMaxRunSnByBatId */
SELECT COALESCE(MAX(run_sn), 0)
FROM sys_batch_run_his
WHERE bat_id = #{batId}

/* batch.selectBatchRunHisResultCode */
SELECT rslt_cd
FROM sys_batch_run_his
WHERE run_sn = #{runSn}
